# PTX source for Swish activation (float16 input/output)
PTX_SOURCE = r'''
.version 7.0
.target sm_80
.address_size 64

.visible .entry swish_kernel(
    .param .u64 input_ptr,
    .param .u64 output_ptr,
    .param .u64 N
)
{
    // Registers
    .reg .pred   %p;
    .reg .u64    %in_ptr, %out_ptr, %idx, %stride, %tmp;
    .reg .u32    %tid32, %blockDim32, %blockIdx32, %gridDim32;
    .reg .f32    %x_f32, %neg_f32, %exp_f32, %den_f32, %sig_f32, %out_f32;
    .reg .b16    %x_h, %out_h;
    .reg .f32    %c_one, %c_inv_ln2;

    // Load kernel parameters
    ld.param.u64 %in_ptr,  [input_ptr];
    ld.param.u64 %out_ptr, [output_ptr];
    ld.param.u64 %tmp,     [N];          // tmp holds N (total elements)

    // Thread identifiers
    mov.u32 %tid32,      %tid.x;
    mov.u32 %blockIdx32, %ctaid.x;
    mov.u32 %blockDim32, %ntid.x;
    mov.u32 %gridDim32,  %nctaid.x;

    // Compute global thread index (64‑bit)
    mad.lo.u32 %tmp, %blockIdx32, %blockDim32, %tid32;
    cvt.u64.u32 %idx, %tmp;

    // Compute stride = gridDim.x * blockDim.x (64‑bit)
    mul.lo.u32 %tmp, %gridDim32, %blockDim32;
    cvt.u64.u32 %stride, %tmp;

    // Constants
    mov.f32 %c_one,        1.0;
    mov.f32 %c_inv_ln2, 1.4426950408889634;   // 1 / ln(2)

LOOP:
    // if (idx >= N) break;
    setp.ge.u64 %p, %idx, %tmp;   // %tmp currently holds N
    @%p bra DONE;

    // Load half (2 bytes)
    mul.lo.u64 %tmp, %idx, 2;
    add.u64 %tmp, %in_ptr, %tmp;
    ld.global.b16 %x_h, [%tmp];

    // Convert to fp32
    cvt.f32.f16 %x_f32, %x_h;

    // neg = -x
    neg.f32 %neg_f32, %x_f32;

    // exp(-x) ≈ 2^{ -x * (1/ln2) }
    mul.f32 %neg_f32, %neg_f32, %c_inv_ln2;
    ex2.approx.f32 %exp_f32, %neg_f32;

    // denom = 1 + exp(-x)
    add.f32 %den_f32, %c_one, %exp_f32;

    // sigmoid = 1 / denom
    rcp.approx.f32 %sig_f32, %den_f32;

    // out = x * sigmoid
    mul.f32 %out_f32, %x_f32, %sig_f32;

    // Convert back to half
    cvt.f16.f32 %out_h, %out_f32;

    // Store result
    mul.lo.u64 %tmp, %idx, 2;
    add.u64 %tmp, %out_ptr, %tmp;
    st.global.b16 [%tmp], %out_h;

    // idx += stride
    add.u64 %idx, %idx, %stride;
    bra LOOP;

DONE:
    ret;
}
'''

# ----------------------------------------------------------------------
# Model wrapper that loads the PTX and launches the kernel
# ----------------------------------------------------------------------
import torch
import torch.nn as nn

# The harness is assumed to provide these two functions
# from ptx_harness import ptx_load, ptx_launch
# (they are available in the execution environment)

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        # Load the PTX module once
        self.module = ptx_load(PTX_SOURCE)
        self.block_size = 256               # threads per block

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda and x.dtype == torch.float16, "Input must be CUDA fp16"
        out = torch.empty_like(x)

        total_elements = x.numel()
        grid = (total_elements + self.block_size - 1) // self.block_size

        # Launch kernel: kernel name, grid dims, block dims, argument tuple
        ptx_launch(
            self.module,
            "swish_kernel",
            (grid,),                 # grid dimensions (only x dimension)
            (self.block_size,),      # block dimensions (only x dimension)
            (x.data_ptr(), out.data_ptr(), total_elements)
        )
        return out
